fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());

    for &c in s.iter() {
        if ('A'..='Z').contains(&c) {
            // ASCII lowercase is +32 in code point
            let lower = ((c as u32) + 32) as u8 as char;
            result.push(lower);
        } else {
            result.push(c);
        }
    }

    result
}